import { Navigate } from 'react-router-dom';

const ProtectedRoute = ({ children, isAuthenticated = false, requiredRole = null, userRole = null }) => {
  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  // Si un rôle spécifique est requis, vérifier que l'utilisateur l'a
  if (requiredRole && userRole !== requiredRole) {
    // Rediriger vers la page appropriée selon le rôle de l'utilisateur
    if (userRole === 'admin') {
      return <Navigate to="/admin" replace />;
    } else {
      return <Navigate to="/dashboard" replace />;
    }
  }

  return children;
};

export default ProtectedRoute;
